mapper.select:
/* PdaInspectPaisMapper.selectBmsInspectResultPicking : 검사피킹 - 박스 피킹 리스트 조회 */
SELECT * FROM ( SELECT P.PACKING_NO , P.IN_PLAN_NO
, CASE WHEN I.IN_PLAN_NO = #{recentFinishedInPlanNo} THEN 0 ELSE 1 END AS LIST_ORDER
, I.IN_NO , I.BL_NO , I.MBL_NO , I.OD_JOB_NO , I.CARGO_REFERENCE_NO , I.CT , I.WT , CASE WHEN SUBSTRING(ISNULL(C.I_TYPE,''), 0, 2) = 'S' THEN '선별 ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.I_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') WHEN SUBSTRING(ISNULL(C.I_TYPE,''), 0, 2) = 'X' THEN 'XR ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.I_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y' AND UPPER(CODE) NOT IN ('C')), '') WHEN SUBSTRING(ISNULL(C.I_TYPE,''), 0, 2) = 'P' THEN '통관 ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.I_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') WHEN SUBSTRING(ISNULL(C.I_TYPE,''), 0, 2) = 'I' THEN '검역 ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.I_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y'), '') END AS BMS_INSPECTION_TYPE , ISNULL(C.CNT,0) AS CNT , C.HSN , P.INSPECT_STATUS , ( SELECT COUNT(PACKING_NO) FROM TB_BMS_IN_PLAN_PKG WITH (NOLOCK) WHERE DELETE_YN = 'N' AND IN_PLAN_NO = I.IN_PLAN_NO AND INSPECT_STATUS <> 'E' ) AS PACKING_NO_CNT , ( SELECT COUNT(INSPECT_STATUS) FROM TB_BMS_IN_PLAN_PKG WITH (NOLOCK) WHERE DELETE_YN = 'N' AND IN_PLAN_NO = I.IN_PLAN_NO AND INSPECT_STATUS = 'P' ) AS INSPECT_STATUS_CNT FROM TB_BMS_IN I WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN_PKG P WITH (NOLOCK) ON I.IN_PLAN_NO = P.IN_PLAN_NO INNER JOIN ( SELECT IN_NO, INSPECTION_TYPE AS I_TYPE, 1 AS CNT, HSN AS HSN FROM TB_BMS_INSPECT_RESULT WHERE INSPECTION_FINISH_YN = 'N'
AND INSPECTION_TYPE IN ('P06','X03','X04','X05','X06','S03','S04','S05','S06','SC' ,'I5','I6','I7','I8','I9','I10','I11','I12' ,'J5','J6','J7','J8','J9','J10','J11','J12' ,'K5','K6','K7','K8','K9','K10','K11','K12' )
) AS C ON I.IN_NO = C.IN_NO WHERE P.DELETE_YN = 'N'
AND I.CD_TYPE = 'Y'
AND I.CD_TYPE <> 'Y'
AND P.IN_PLAN_NO = #{inPlanNo}
AND P.PACKING_NO = #{packingNo}
AND I.BL_NO = #{blNo}
AND P.INSPECT_STATUS <> #{inspectStatus}
) RST WHERE RST.PACKING_NO_CNT <> RST.INSPECT_STATUS_CNT
AND INSPECT_STATUS_CNT <> 0
ORDER BY
LIST_ORDER,
MBL_NO, HSN

/* PdaInspectPaisMapper.selectBmsInForAddInspectResult : 검사피킹 - 박스번호로 반입 조회 */ SELECT TOP 1 PP.PACKING_NO , PP.IN_PLAN_NO , I.IN_NO , I.BL_NO , I.MBL_NO , I.OD_JOB_NO , I.CARGO_REFERENCE_NO , I.CT , I.WT , I.SE_INSPECTION_CODE , I.XRAY_INSPECTION_CODE , I.PALN5EM_INSPECTION_CODE , PP.INSPECT_STATUS FROM TB_BMS_IN I WITH (NOLOCK) JOIN TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) ON I.IN_PLAN_NO = PP.IN_PLAN_NO WHERE PP.DELETE_YN = 'N'
AND PP.PACKING_NO = #{packingNo}
AND PP.IN_PLAN_NO = #{inPlanNo}
AND I.BL_NO = #{blNo}

mapper.update:
	/* PdaInspectPaisMapper.updateBmsInPlanPkgInspectStatus : 박스 검사여부 update */
	UPDATE PP
	   SET PP.INSPECT_STATUS = #{inspectStatus}
	     , PP.UPDATE_USER_ID = #{updateUserId}
         , PP.UPDATE_DATE_TIME = GETDATE()
	  FROM TB_BMS_IN_PLAN_PKG PP
	  JOIN TB_BMS_IN_PLAN P WITH (NOLOCK)
	    ON PP.IN_PLAN_NO = P.IN_PLAN_NO
	 WHERE PP.PACKING_NO = #{packingNo}

	   AND PP.IN_PLAN_NO = #{inPlanNo}


	   AND P.BL_NO = #{blNo}

/* PdaInspectPaisMapper.updateBmsInspectResultStartInfo : 검사피킹 update */
UPDATE TB_BMS_INSPECT_RESULT SET 
	INSPECTION_START_USER_ID = #{registerUserId}
  , INSPECTION_START_DATE_TIME = GETDATE()
WHERE IN_NO = #{inNo}

mapper.select:
/* PdaInspectPaisMapper.selectBmsInspectScanLogInfo : 검사 스캔로그 조회 */
SELECT SCAN_NO , BL_NO , SCAN_DATE , SCAN_RESULT , INSPECTION_STATUS , REGISTER_USER_ID , ISNULL((SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = tbis.REGISTER_USER_ID),'') AS REGISTER_USER_NAME , REGISTER_DATE_TIME FROM TB_BMS_INSPECT_SCAN tbis WHERE SCAN_DATE BETWEEN CONVERT(VARCHAR(10), ISNULL(#{srchScanDate},''), 120) AND CONVERT(VARCHAR(10), GETDATE(), 120)
AND INSPECTION_STATUS = #{srchInspectStatus}
ORDER BY REGISTER_DATE_TIME DESC

mapper.insert:
/* PdaInspectPaisMapper.insertBmsInspectScanLog : 검사 스캔로그 저장 */
INSERT INTO TB_BMS_INSPECT_SCAN (
	  SCAN_NO
	, INSPECTION_STATUS
	, BL_NO
	, SCAN_RESULT
	, SCAN_DATE
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
)
VALUES(
	  #{packingNo}
	, #{inspectStatus}
	, #{blNo}
	, #{result}
	, CONVERT(VARCHAR(10),GETDATE(),120)
	, #{registerUserId}
	, GETDATE()
)

mapper.select:
/* PdaInspectPaisMapper.selectOneBmsInByPackingNo : 박스번호에 의한 박스조회 */ SELECT TOP 1 I.BL_NO , I.MBL_NO , I.IN_NO , I.IN_PLAN_NO , I.CT FROM TB_BMS_IN I WITH (NOLOCK) INNER JOIN (SELECT IN_NO , INSPECTION_TYPE AS INSPECTION_TYPE , HSN AS HSN FROM TB_BMS_INSPECT_RESULT WHERE INSPECTION_FINISH_YN = 'N' AND INSPECTION_TYPE IN ( 'P06','X03','X04','X05','X06','S03','S04','S05','S06','SC' ,'I5','I6','I7','I8','I9','I10','I11','I12' ,'J5','J6','J7','J8','J9','J10','J11','J12' ,'K5','K6','K7','K8','K9','K10','K11','K12' ) AND INSPECTION_START_USER_ID <> '' -- AND INSPECTION_START_DATE_TIME >= CAST(CAST(GETDATE() AS DATE) AS DATETIME)
) AS C ON I.IN_NO = C.IN_NO WHERE
I.CD_TYPE = 'Y'
I.CD_TYPE <> 'Y'
AND I.IN_PLAN_NO = ( SELECT TOP 1 PP.IN_PLAN_NO FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO WHERE PP.PACKING_NO = #{scanPackingNo}
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}
)

/* PdaInspectPaisMapper.selectOneBmsInByPackingNoV2 : 박스번호에 의한 박스조회 */ SELECT TOP 1 I.BL_NO , I.MBL_NO , I.IN_NO , I.IN_PLAN_NO , I.CT FROM TB_BMS_IN I WITH (NOLOCK) INNER JOIN (SELECT IN_NO , INSPECTION_TYPE AS INSPECTION_TYPE , HSN AS HSN FROM TB_BMS_INSPECT_RESULT WHERE INSPECTION_FINISH_YN = 'N' AND INSPECTION_TYPE IN ( 'P06','X03','X04','X05','X06','S03','S04','S05','S06','SC' ,'I5','I6','I7','I8','I9','I10','I11','I12' ,'J5','J6','J7','J8','J9','J10','J11','J12' ,'K5','K6','K7','K8','K9','K10','K11','K12' ) -- AND INSPECTION_START_USER_ID <> '' -- AND INSPECTION_START_DATE_TIME >= CAST(CAST(GETDATE() AS DATE) AS DATETIME)
) AS C ON I.IN_NO = C.IN_NO WHERE 1=1
AND I.IN_PLAN_NO = ( SELECT TOP 1 PP.IN_PLAN_NO FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO WHERE PP.PACKING_NO = #{scanPackingNo}
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}
)

mapper.insert:
/* PdaInspectPaisMapper.insertInspectScanLog : 검사 스캔로그 저장 */
INSERT INTO TB_BMS_INSPECT_SCAN (
	  SCAN_NO
	, INSPECTION_STATUS
	, BL_NO
	, SCAN_RESULT
	, SCAN_DATE
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
)
VALUES(
	#{packingNo}
	, #{inspectionStatus}
	, #{blNo}
	, #{result}
	, CONVERT(VARCHAR(10),GETDATE(),120)
	, #{registerUserId}
	, GETDATE()
)

mapper.select:
/* PdaInspectPaisMapper.selectPkgByPackingNo : 박스번호에 의한 박스조회 */
SELECT TOP 1
	_pkg.BL_NO
	, _pkg.IN_PLAN_NO
	, _pkg.INSPECT_STATUS
FROM TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK)
JOIN TB_BMS_IN_PLAN _inPlan WITH (NOLOCK)
  ON _pkg.IN_PLAN_NO = _inPlan.IN_PLAN_NO
WHERE _pkg.PACKING_NO = #{scanPackingNo}

	AND _pkg.IN_PLAN_NO = #{srchInPlanNo}


	AND _inPlan.BL_NO = #{srchBlNo}

	/* PdaInspectPaisMapper.checkAllInspectResultNotFinish : 완료되지않은 검사결과 데이터 갯수 체크 */
	SELECT
		COUNT(*) AS CNT
	FROM TB_BMS_INSPECT_RESULT
	WHERE IN_NO IN (
	    	SELECT IN_NO
	    	FROM TB_BMS_IN WITH (NOLOCK)
	    	WHERE IN_PLAN_NO = #{inPlanNo}
    	)
    	AND INSPECTION_FINISH_YN <> 'Y'

/* PdaInspectPaisMapper.selectPkgBmsInByInPlanNo : */ SELECT I.IN_PLAN_NO , I.IN_NO , I.BL_NO , I.MBL_NO , I.CT , I.WT , _pkg.PACKING_NO , _pkg.INSPECT_STATUS , C.INSPECTION_TYPE AS BMS_INSPECTION_TYPE , C.HSN FROM TB_BMS_IN I WITH (NOLOCK) INNER JOIN (SELECT IN_NO , INSPECTION_TYPE AS INSPECTION_TYPE , HSN AS HSN FROM TB_BMS_INSPECT_RESULT WHERE INSPECTION_FINISH_YN = 'N' AND INSPECTION_TYPE IN ( 'P06','X03','X04','X05','X06','S03','S04','S05','S06','SC' ,'I5','I6','I7','I8','I9','I10','I11','I12' ,'J5','J6','J7','J8','J9','J10','J11','J12' ,'K5','K6','K7','K8','K9','K10','K11','K12' ) AND INSPECTION_START_USER_ID <> '' -- AND INSPECTION_START_DATE_TIME >= CAST(CAST(GETDATE() AS DATE) AS DATETIME)
) AS C ON I.IN_NO = C.IN_NO INNER JOIN TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK) ON _pkg.IN_PLAN_NO = I.IN_PLAN_NO AND _pkg.DELETE_YN ='N' WHERE I.IN_PLAN_NO IN (#{item})
AND I.CD_TYPE = 'Y'
AND I.CD_TYPE <> 'Y'
ORDER BY I.MBL_NO, C.HSN

/* PdaInspectPaisMapper.selectInspectResultNotFinished : (BL)반입단위그룹의 finished안된 검사결과 조회 */
SELECT
	*
FROM TB_BMS_INSPECT_RESULT
WHERE IN_NO = #{inNo}
	AND INSPECTION_FINISH_YN = 'N'

mapper.update:
	/* PdaInspectPaisMapper.updateInspectStatusOfPkg : 박스 검사상태 업데이트 */
    UPDATE PP
       SET PP.INSPECT_STATUS = #{inspectStatus}
         , PP.UPDATE_USER_ID = #{updateUserId}
         , PP.UPDATE_DATE_TIME = GETDATE()
      FROM TB_BMS_IN_PLAN_PKG PP
      JOIN TB_BMS_IN_PLAN P WITH (NOLOCK)
	    ON PP.IN_PLAN_NO = P.IN_PLAN_NO
     WHERE PP.PACKING_NO = #{scanPackingNo}

	   AND PP.IN_PLAN_NO = #{srchInPlanNo}


	   AND P.BL_NO = #{srchBlNo}

	/* PdaInspectPaisMapper.updateInspectStatusOfAllPkg : 박스 검사상태 일괄 업데이트 */
    UPDATE TB_BMS_IN_PLAN_PKG
    SET INSPECT_STATUS = #{inspectStatus}
        , UPDATE_USER_ID = #{updateUserId}
        , UPDATE_DATE_TIME = GETDATE()
    WHERE IN_PLAN_NO IN (#{item.inPlanNo})

	/* PdaInspectPaisMapper.updateInspectResultFinishByInspectionTypeList : 검사결과 업데이트 */
    UPDATE TB_BMS_INSPECT_RESULT
    SET 
    	INSPECTION_FINISH_YN = #{inspectionFinishYn},
		INSPECTION_FINISH_REMARKS = #{remarks},
		INSPECTION_FINISH_USER_ID = #{updateUserId},
		INSPECTION_FINISH_DATE_TIME = GETDATE()
    WHERE IN_NO = #{inNo}
    	AND INSPECTION_TYPE = #{inspectionResultType}

	/* PdaInspectPaisMapper.updateBmsInAllInpectionFinishYnByInNoList : 반입 전체검사완료여부 일괄 업데이트 */
    UPDATE TB_BMS_IN
    SET ALL_INSPECTION_FINISH_YN = #{allInspectionFinishYn}
        , UPDATE_USER_ID = #{updateUserId}
        , UPDATE_DATE_TIME = GETDATE()
    WHERE IN_NO = #{inNo}

mapper.select:
/* PdaInspectPaisMapper.selectBmsInByInPlanNo : 반입번호로 검사결과 조회 */
SELECT
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE 
	IN_PLAN_NO = #{inPlanNo}

/* PdaInspectPaisMapper.selectInspectResultCodeValueByInPlanNoOrInNo : 반입예정번호로 검사결과 조회 */ SELECT CASE WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'S' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') END AS SE_INSPECTION_CODE , CASE WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'X' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y' AND UPPER(CODE) NOT IN ('C')), '') END AS XRAY_INSPECTION_CODE , CASE WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'P' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') END AS PALN5EM_INSPECTION_CODE , CASE WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'I' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y'), '') END AS INSPECTION_TYPE , _in.BL_NO AS BL_NO , _in.OD_JOB_NO FROM TB_BMS_INSPECT_RESULT AS C LEFT JOIN TB_BMS_IN _in WITH (NOLOCK) ON _in.IN_NO = C.IN_NO WHERE 1=1
AND _in.IN_NO = #{inNo}
AND _in.IN_PLAN_NO = #{inPlanNo}
AND INSPECTION_FINISH_YN = 'N'

mapper.insert:
	/* PdaInspectPaisMapper.insertInspectResult : 검사결과 추가 */
    INSERT INTO TB_BMS_INSPECT_RESULT
    (
    	IN_NO
		, INSPECTION_TYPE
		, HSN
		, REGISTER_USER_ID
		, REGISTER_DATE_TIME
    )
    VALUES (
    	#{inNo}
    	, #{inspectionType}
    	, SUBSTRING(#{cargoReferenceNo}, 16, 4)
    	, #{updateUserId}
    	, GETDATE()
    )

mapper.select:
/* PdaInspectPaisMapper.selectInspectResult : 검사사유관리 - 조회 */ WITH R AS ( SELECT IR.*, LEFT(IR.INSPECTION_TYPE, 1) AS PREFIX, ROW_NUMBER() OVER ( PARTITION BY IR.IN_NO, LEFT(IR.INSPECTION_TYPE, 1) ORDER BY IR.REGISTER_DATE_TIME DESC, -- 최신 생성 날짜 IR.INSPECTION_FINISH_DATE_TIME DESC -- 취소든변경이든 최신 최종결과 날짜 ) AS RN FROM TB_BMS_INSPECT_RESULT IR WITH (NOLOCK) )
SELECT I.CT AS CT , I.IN_NO , I.CARGO_REFERENCE_NO , I.REMARKS_3 AS INSPECT_REMARK , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'S' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') END AS SE_INSPECTION_CODE_NAME , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'X' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y' AND UPPER(CODE) NOT IN ('C')), '') END AS XRAY_INSPECTION_CODE_NAME , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'P' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') END AS PALN5EM_INSPECTION_CODE_NAME , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'I' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y'), '') WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'J' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y'), '') WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'K' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y'), '') END AS INSPECTION_TYPE_NAME
, CASE WHEN ISNULL(R.INSPECTION_TYPE,'') = 'B' and ISNULL(R.INSPECTION_FINISH_YN,'') = 'N' THEN '검사중' END AS BIG_SIZE_YN_NAME , CASE WHEN ISNULL(R.INSPECTION_TYPE,'') = 'T' and ISNULL(R.INSPECTION_FINISH_YN,'') = 'N' THEN '검사중' END AS INTELLECTUAL_PROP_YN_NAME , CASE WHEN ISNULL(R.INSPECTION_TYPE,'') = 'A' and ISNULL(R.INSPECTION_FINISH_YN,'') = 'N' THEN '검사중' END AS INSPECTION_CUSTOMS_YN_NAME
, CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'S' THEN ISNULL(R.INSPECTION_TYPE,'') END AS SE_INSPECTION_CODE_TYPE , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'X' THEN ISNULL(R.INSPECTION_TYPE,'') END AS XRAY_INSPECTION_CODE_TYPE , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'P' THEN ISNULL(R.INSPECTION_TYPE,'') END AS PALN5EM_INSPECTION_CODE_TYPE , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) IN ('I','J','K') THEN ISNULL(R.INSPECTION_TYPE,'') END AS INSPECTION_TYPE_TYPE
, CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'S' THEN ISNULL(INSPECTION_FINISH_REMARKS, '') END AS SE_INSPECTION_REMARK , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'X' THEN ISNULL(INSPECTION_FINISH_REMARKS, '') END AS XRAY_INSPECTION_REMARK , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'P' THEN ISNULL(INSPECTION_FINISH_REMARKS, '') END AS PALN5EM_INSPECTION_REMARK , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'I' THEN ISNULL(INSPECTION_FINISH_REMARKS, '') END AS INSPECTION_TYPE_REMARK
, CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'S' THEN ISNULL(R.INSPECTION_FINISH_YN, '') END AS SE_INSPECTION_FINISH_YN , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'X' THEN ISNULL(R.INSPECTION_FINISH_YN, '') END AS XRAY_INSPECTION_FINISH_YN , CASE WHEN SUBSTRING(ISNULL(R.INSPECTION_TYPE,''), 0, 2) = 'P' THEN ISNULL(R.INSPECTION_FINISH_YN, '') END AS PALN5EM_INSPECTION_FINISH_YN FROM TB_BMS_IN I WITH (NOLOCK) LEFT JOIN R ON R.IN_NO = I.IN_NO AND R.RN = 1 WHERE I.IN_PLAN_NO = #{srchInPlanNo}

mapper.update:
/* PdaInspectPaisMapper.updateInspectResultRemark : 검사사유관리 - 검사결과 비고 저장 */
UPDATE 
	TB_BMS_INSPECT_RESULT
SET
	REGISTER_USER_ID = #{updateUserId}
	, REGISTER_DATE_TIME = GETDATE()
	, INSPECTION_FINISH_REMARKS = #{inspectResultRemark}
WHERE 
	IN_NO = #{inNo}
	AND SUBSTRING(ISNULL(INSPECTION_TYPE,''), 0, 2) = #{inspectTypeCode}

/* PdaInspectPaisMapper.updateInspectResultRemarkByKey : 검사사유관리 - 검사결과 비고 저장 */
UPDATE 
	TB_BMS_INSPECT_RESULT
SET
	INSPECTION_FINISH_USER_ID = #{updateUserId}
	, INSPECTION_FINISH_REMARKS = #{inspectResultRemark}

	, INSPECTION_FINISH_YN = #{inspectionFinishYn}



			, INSPECTION_FINISH_DATE_TIME = GETDATE()


			, INSPECTION_FINISH_DATE_TIME = ''


WHERE 
	IN_NO = #{inNo}
	AND INSPECTION_TYPE =  #{inspectionTypeCode}

/* PdaInspectPaisMapper.updateInspectResultRemark : 검사사유관리 - 전체 검사 여부 완료 저장 */
UPDATE 
	TB_BMS_IN
SET 
	REMARKS_3 = #{inspectRemark}

		, ALL_INSPECTION_FINISH_YN = #{allInspectionFinishYn}

	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE 
	IN_NO = #{inNo}

mapper.select:
/* PdaInspectPaisMapper.selectInspectResultByInNo : (BL)반입단위그룹의 존재하는 검사결과 조회 */
SELECT
	*
FROM TB_BMS_INSPECT_RESULT WITH (NOLOCK)
WHERE IN_NO = #{inNo}

/* PdaInspectPaisMapper.selectNotFinishedInspectResultByInPlanNo : (BL)반입단위그룹의 존재하는 검사결과 조회 */
SELECT
	*
FROM TB_BMS_INSPECT_RESULT WITH (NOLOCK)
WHERE IN_NO = (
	SELECT IN_NO
	FROM TB_BMS_IN WITH (NOLOCK)
	WHERE IN_PLAN_NO = #{inPlanNo}
) AND INSPECTION_FINISH_YN = 'N'

/* PdaInspectPaisMapper.selectBmsInsInNo : 이고반입 조회 */
SELECT TOP 1
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
AND IN_CLASS = '21'

/* PdaInspectPaisMapper.selectBmsInsOutNo : 이고반출 조회 */
SELECT TOP 1
	*
FROM TB_BMS_OUT WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
AND OUT_CLASS = '61'

mapper.update:
/* PdaInspectPaisMapper.updateInsComplete : 검사사유관리 - 이고검사완료 처리 */
UPDATE 
	TB_BMS_INSPECT_RESULT
SET
	  INSPECTION_FINISH_YN = 'Y'
	, INSPECTION_FINISH_REMARKS = '이상없음'
	, INSPECTION_FINISH_USER_ID = #{updateUserId}
	, INSPECTION_FINISH_DATE_TIME = GETDATE()
WHERE 
	IN_NO = #{inNo}

	AND INSPECTION_TYPE IN

		#{type}

mapper.select:
/* PdaInspectPaisMapper.selectBmsInsCompleteYn : 검사완료 여부 조회 */
SELECT
	IN_NO
	,INSPECTION_FINISH_YN
FROM TB_BMS_INSPECT_RESULT
WHERE IN_NO = #{inNo}

/* PdaInspectPaisMapper.selectBmsInByCargoNoOrInNoOrInPlanNo : 반입 조회 */
SELECT TOP 1
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}

/* PdaInspectPaisMapper.selectBmsInByInNoOrInPlanNo : 반입 조회 */
SELECT TOP 1
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE 


		IN_NO = #{inNo}


		IN_PLAN_NO = #{inPlanNo}
